export const GAME_LIMITS = Object.freeze({
  mismatchMs: 800,
  maxMoves: 999_999,
  maxElapsedMs: 359_999_999,
  snapshotBytes: 65_536,
  replayBytes: 1_048_576,
  replayActions: 10_000
});

export const supportedSizes = [4, 6, 8, 10, 12, 14, 16] as const;
export type BoardSize = (typeof supportedSizes)[number];

export type Board = Readonly<{
  code: string;
  size: BoardSize;
  deck: readonly number[];
}>;

export type Selection =
  | Readonly<{ kind: "closed" }>
  | Readonly<{ kind: "one"; index: number }>
  | Readonly<{ kind: "mismatch"; first: number; second: number; remainingMs: number }>;

export type GameState = Readonly<{
  board: Board;
  matched: readonly number[];
  selection: Selection;
  moves: number;
  elapsedMs: number;
  started: boolean;
}>;

export const closedSelection: Selection = Object.freeze({ kind: "closed" });
import { supportedSizes, type Board, type BoardSize } from "./types.ts";

const modulus = 2_147_483_647;
const drawRange = modulus - 1;

export function parseBoardCode(text: string): Readonly<{ code: string; size: BoardSize; seed: number }> | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(text);
  if (match === null) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!supportedSizes.some((value) => value === size) || !Number.isSafeInteger(seed) || seed > drawRange) return null;
  return { code: text, size: size as BoardSize, seed };
}

function nextState(state: number): number {
  return (state * 16_807) % modulus;
}

function drawBounded(state: number, bound: number): Readonly<{ state: number; value: number }> {
  const limit = Math.floor(drawRange / bound) * bound;
  let next = state;
  while (true) {
    next = nextState(next);
    const value = next - 1;
    if (value < limit) return { state: next, value: value % bound };
  }
}

export function createBoard(boardCode: string): Board | null {
  const parsed = parseBoardCode(boardCode);
  if (parsed === null) return null;
  const count = parsed.size * parsed.size;
  const deck: number[] = [];
  for (let face = 0; face < count / 2; face += 1) deck.push(face, face);
  let state = parsed.seed;
  for (let index = count - 1; index > 0; index -= 1) {
    const drawn = drawBounded(state, index + 1);
    state = drawn.state;
    const current = deck[index];
    const other = deck[drawn.value];
    if (current === undefined || other === undefined) return null;
    deck[index] = other;
    deck[drawn.value] = current;
  }
  return Object.freeze({ code: parsed.code, size: parsed.size, deck: Object.freeze(deck) });
}

export function createGame(boardCode: string) {
  const board = createBoard(boardCode);
  if (board === null) throw new RangeError("Invalid board code.");
  return Object.freeze({
    board,
    matched: Object.freeze([]) as readonly number[],
    selection: Object.freeze({ kind: "closed" as const }),
    moves: 0,
    elapsedMs: 0,
    started: false
  });
}
import { GAME_LIMITS, closedSelection, type GameState, type Selection } from "./types.ts";

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

function addMove(moves: number): number {
  return Math.min(GAME_LIMITS.maxMoves, moves + 1);
}

function faceAt(state: GameState, index: number): number | undefined {
  return state.board.deck[index];
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.board.deck.length || isWon(state)) return state;
  if (state.matched.includes(index) || state.selection.kind === "mismatch") return state;

  if (state.selection.kind === "closed") {
    return { ...state, selection: { kind: "one", index }, started: true };
  }

  if (state.selection.index === index) return state;
  const first = state.selection.index;
  const second = index;
  const moves = addMove(state.moves);
  if (faceAt(state, first) === faceAt(state, second)) {
    return { ...state, matched: [...state.matched, first, second], selection: closedSelection, moves, started: true };
  }
  const selection: Selection = {
    kind: "mismatch", first, second, remainingMs: GAME_LIMITS.mismatchMs
  };
  return { ...state, selection, moves, started: true };
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds < 0) throw new RangeError("Time must be finite and nonnegative.");
  if (milliseconds === 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(GAME_LIMITS.maxElapsedMs, state.elapsedMs + milliseconds);
  if (state.selection.kind !== "mismatch") return { ...state, elapsedMs };
  const remainingMs = state.selection.remainingMs - milliseconds;
  const selection = remainingMs <= 0
    ? closedSelection
    : { ...state.selection, remainingMs };
  return { ...state, elapsedMs, selection };
}
