import { supportedSizes, type BoardSize } from "../types.ts";

export const PREFERENCES_KEY = "neon-pairs.preferences.v1";
export type Preferences = Readonly<{
  size: BoardSize;
  bestScores: Partial<Record<BoardSize, number>>;
}>;
type StoragePort = Pick<Storage, "getItem" | "setItem">;

function record(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function isBoardSize(value: unknown): value is BoardSize {
  return typeof value === "number" && supportedSizes.some((size) => size === value);
}

function browserStorage(): StoragePort | null {
  try {
    return typeof window === "undefined" ? null : window.localStorage;
  } catch {
    return null;
  }
}

function cleanPreferences(value: unknown): Preferences {
  if (!record(value)) return { size: 4, bestScores: {} };
  const size = isBoardSize(value.size) ? value.size : 4;
  const scores: Partial<Record<BoardSize, number>> = {};
  if (record(value.bestScores)) {
    for (const boardSize of supportedSizes) {
      const score = value.bestScores[boardSize];
      if (typeof score === "number" && Number.isSafeInteger(score) && score >= 0 && score <= 999_999) {
        scores[boardSize] = score;
      }
    }
  }
  return { size, bestScores: scores };
}

export function readPreferences(storage: StoragePort | null = browserStorage()): Preferences {
  if (storage === null) return cleanPreferences(null);
  try {
    const value = storage.getItem(PREFERENCES_KEY);
    if (value === null) return cleanPreferences(null);
    try {
      return cleanPreferences(JSON.parse(value) as unknown);
    } catch {
      return cleanPreferences(null);
    }
  } catch {
    return cleanPreferences(null);
  }
}

export function writePreferences(
  preferences: Preferences,
  storage: StoragePort | null = browserStorage()
): void {
  if (storage === null) return;
  try {
    storage.setItem(PREFERENCES_KEY, JSON.stringify(cleanPreferences(preferences)));
  } catch {
    // Storage is optional; a failed write must not interrupt play.
  }
}
import { describe, expect, it } from "vitest";
import { PREFERENCES_KEY, readPreferences, writePreferences } from "./storage.ts";

function memoryStorage(seed: Readonly<Record<string, string>> = {}) {
  const values = new Map(Object.entries(seed));
  const writes: string[] = [];
  return {
    values,
    writes,
    getItem: (key: string) => values.get(key) ?? null,
    setItem: (key: string, value: string) => {
      writes.push(key);
      values.set(key, value);
    }
  };
}

describe("session preferences", () => {
  it("uses defaults for missing, malformed or unrecognized saved settings", () => {
    expect(readPreferences(null)).toEqual({ size: 4, bestScores: {} });
    expect(readPreferences(memoryStorage({ [PREFERENCES_KEY]: "{" }))).toEqual({ size: 4, bestScores: {} });
    const saved = memoryStorage({ [PREFERENCES_KEY]: JSON.stringify({
      size: 5,
      bestScores: { 4: 0, 6: 999_999, 8: -1, 10: 1.5, 12: 1_000_000, 18: 2 }
    }) });
    expect(readPreferences(saved)).toEqual({ size: 4, bestScores: { 4: 0, 6: 999_999 } });
  });

  it("catches storage failures and writes only the game preference key", () => {
    const failed = {
      getItem: () => { throw new Error("blocked"); },
      setItem: () => { throw new Error("blocked"); }
    };
    expect(readPreferences(failed)).toEqual({ size: 4, bestScores: {} });
    expect(() => writePreferences({ size: 8, bestScores: { 8: 11 } }, failed)).not.toThrow();

    const saved = memoryStorage({ other: "untouched" });
    writePreferences({ size: 8, bestScores: { 8: 11 } }, saved);
    expect(saved.writes).toEqual([PREFERENCES_KEY]);
    expect(saved.values.get("other")).toBe("untouched");
    expect(readPreferences(saved)).toEqual({ size: 8, bestScores: { 8: 11 } });
  });
});

