import { useEffect, useRef, useState } from "react";
import { createGame, parseBoardCode } from "../board.ts";
import { activateCard, advanceGame, isWon } from "../state.ts";
import { decodeSnapshot, encodeSnapshot } from "../snapshot.ts";
import type { BoardSize, GameState } from "../types.ts";
import type { GameSession, SessionAnnouncement } from "./contracts.ts";
import { isBoardSize, readPreferences, writePreferences, type Preferences } from "./storage.ts";

const randomSeedLimit = 2_147_483_646;
const clockIntervalMs = 32;

function newCode(size: BoardSize, currentCode?: string): string {
  let seed = Math.floor(Math.random() * randomSeedLimit) + 1;
  const current = currentCode === undefined ? null : parseBoardCode(currentCode);
  if (current?.size === size && current.seed === seed) seed = seed === randomSeedLimit ? 1 : seed + 1;
  return `np1-${size}-${seed}`;
}

function displayTime(milliseconds: number): string {
  const seconds = Math.floor(milliseconds / 1000);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
}

function initialSession(): Readonly<{ preferences: Preferences; game: GameState }> {
  const preferences = readPreferences();
  return { preferences, game: createGame(newCode(preferences.size)) };
}

export function useGameSession(): GameSession {
  const [initial] = useState(initialSession);
  const [game, setGame] = useState(initial.game);
  const [preferences, setPreferences] = useState(initial.preferences);
  const [isPaused, setIsPaused] = useState(false);
  const [visible, setVisible] = useState(() => typeof document === "undefined" || document.visibilityState !== "hidden");
  const [isCelebrating, setIsCelebrating] = useState(false);
  const [boardRevision, setBoardRevision] = useState(0);
  const [announcement, setAnnouncement] = useState<SessionAnnouncement>({ id: 0, text: "" });
  const [loadStatus, setLoadStatus] = useState("");
  const gameRef = useRef(game);
  const preferencesRef = useRef(preferences);
  const pausedRef = useRef(false);
  const visibleRef = useRef(visible);
  const clockActive = useRef(false);
  const lastClockTime = useRef(0);
  const generation = useRef(0);
  const announcementId = useRef(0);
  const revisionRef = useRef(0);
  const celebrationTimer = useRef<number | null>(null);

  function commitGame(next: GameState): void {
    gameRef.current = next;
    setGame(next);
  }

  function syncClock(now: number): void {
    if (!clockActive.current) return;
    const elapsed = Math.max(0, now - lastClockTime.current);
    lastClockTime.current = now;
    if (elapsed > 0) commitGame(advanceGame(gameRef.current, elapsed));
  }

  function startClock(now: number): void {
    if (visibleRef.current && !pausedRef.current && gameRef.current.started && !isWon(gameRef.current)) {
      lastClockTime.current = now;
      clockActive.current = true;
    }
  }

  function announce(text: string): void {
    announcementId.current += 1;
    setAnnouncement({ id: announcementId.current, text });
  }

  function savePreferences(next: Preferences): void {
    preferencesRef.current = next;
    setPreferences(next);
    writePreferences(next);
  }

  function rememberSize(size: BoardSize): void {
    savePreferences({ ...preferencesRef.current, size });
  }

