import { forwardRef, useImperativeHandle, useRef, useState } from "react";
import type { KeyboardEvent } from "react";
import type { GameState } from "../types.ts";
import { Card } from "./Card.tsx";
import "./board.css";

export type BoardHandle = Readonly<{ focusRemembered(): void }>;
export type BoardProps = Readonly<{
  game: GameState;
  onActivate(index: number): void;
}>;

export const Board = forwardRef<BoardHandle, BoardProps>(function Board({ game, onActivate }, forwardedRef) {
  const size = game.board.size;
  const [tabStop, setTabStop] = useState(0);
  const cards = useRef<Array<HTMLButtonElement | null>>(
    Array.from({ length: size * size }, () => null)
  );

  useImperativeHandle(forwardedRef, () => ({
    focusRemembered() {
      cards.current[tabStop]?.focus();
    }
  }), [tabStop]);

  function moveFocus(index: number, event: KeyboardEvent<HTMLButtonElement>): void {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    let target = index;
    if (event.key === "ArrowLeft" && index % size > 0) target = index - 1;
    else if (event.key === "ArrowRight" && index % size < size - 1) target = index + 1;
    else if (event.key === "ArrowUp" && index >= size) target = index - size;
    else if (event.key === "ArrowDown" && index + size < size * size) target = index + size;
    else return;
    event.preventDefault();
    cards.current[target]?.focus();
  }

  function cardFace(index: number): number | undefined {
    if (game.matched.includes(index)) return game.board.deck[index];
    if (game.selection.kind === "one" && game.selection.index === index) return game.board.deck[index];
    if (game.selection.kind === "mismatch" && (game.selection.first === index || game.selection.second === index)) {
      return game.board.deck[index];
    }
    return undefined;
  }

  const widest = size * 88 + (size - 1) * 6;
  const narrowest = size * 44 + (size - 1) * 6;

  return (
    <div className="board-scroll" aria-label={`${size} by ${size} card board`}>
      <div
        className="board-grid"
        role="group"
        aria-label={`${size} by ${size} cards`}
        style={{
          gridTemplateColumns: `repeat(${size}, minmax(44px, 88px))`,
          width: `min(100%, ${widest}px)`,
          minWidth: `${narrowest}px`
        }}
      >
        {game.board.deck.map((_, index) => (
          <Card
            key={index}
            index={index}
            size={size}
            face={cardFace(index)}
            matched={game.matched.includes(index)}
            tabStop={index === tabStop}
            buttonRef={(element) => { cards.current[index] = element; }}
            onActivate={onActivate}
            onFocus={(focusedIndex) => {
              setTabStop(focusedIndex);
              cards.current[focusedIndex]?.scrollIntoView({ block: "nearest", inline: "nearest" });
            }}
            onKeyDown={(event) => moveFocus(index, event)}
          />
        ))}
      </div>
    </div>
  );
});

import type { CSSProperties, FocusEventHandler, KeyboardEventHandler, MouseEventHandler } from "react";
import { CardBack, FaceArtwork, faceName } from "./faces.tsx";
import "./card.css";

export type CardProps = Readonly<{
  index: number;
  size: number;
  face?: number;
  matched: boolean;
  tabStop: boolean;
  buttonRef(element: HTMLButtonElement | null): void;
  onActivate(index: number): void;
  onFocus(index: number): void;
  onKeyDown: KeyboardEventHandler<HTMLButtonElement>;
}>;

export function Card({ index, size, face, matched, tabStop, buttonRef, onActivate, onFocus, onKeyDown }: CardProps) {
  const row = Math.floor(index / size) + 1;
  const column = index % size + 1;
  const revealed = face !== undefined;
  const label = revealed
    ? `Row ${row}, column ${column}, ${faceName(face)}, ${matched ? "matched" : "revealed"}`
    : `Row ${row}, column ${column}, closed`;
  const cardStyle = { scrollMargin: "6px" } satisfies CSSProperties;
  const handleClick: MouseEventHandler<HTMLButtonElement> = (event) => {
    if (event.button !== 0 || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    onActivate(index);
  };
  const handleFocus: FocusEventHandler<HTMLButtonElement> = () => onFocus(index);

  return (
    <button
      ref={buttonRef}
      className={`memory-card${revealed ? " is-revealed" : ""}${matched ? " is-matched" : ""}`}
      type="button"
      aria-label={label}
      aria-disabled={matched ? "true" : undefined}
      tabIndex={tabStop ? 0 : -1}
      style={cardStyle}
      onClick={handleClick}
      onFocus={handleFocus}
      onKeyDown={onKeyDown}
    >
      {revealed ? <FaceArtwork face={face} /> : <CardBack />}
      {matched && <span className="matched-mark" aria-hidden="true">✓</span>}
    </button>
  );
}
