import { useEffect, useRef, useState } from "react";
import type { BoardSize } from "./game/types.ts";
import { supportedSizes } from "./game/types.ts";
import { isWon } from "./game/state.ts";
import { useGameSession } from "./game/session/useGameSession.ts";
import { formatElapsed } from "./game/session/deal.ts";
import { Board, type BoardHandle } from "./game/board/Board.tsx";
import { ReproductionControls } from "./game/controls/ReproductionControls.tsx";

export function Game() {
  const session = useGameSession();
  const boardRef = useRef<BoardHandle>(null);
  const [boardCodeDraft, setBoardCodeDraft] = useState(session.game.board.code);
  const [snapshotDraft, setSnapshotDraft] = useState("");
  const won = isWon(session.game);
  const pairs = session.game.matched.length / 2;

  useEffect(() => {
    setBoardCodeDraft(session.game.board.code);
  }, [session.boardRevision, session.game.board.code]);

  function chooseSize(value: string): void {
    const size = supportedSizes.find((supported) => supported === Number(value));
    if (size !== undefined) session.changeSize(size);
  }

  function exportSnapshot(): void {
    setSnapshotDraft(session.exportSnapshot());
  }

  function resume(): void {
    boardRef.current?.focusRemembered();
    session.resume();
  }

  return (
    <main className="game-shell">
      <header className="game-header">
        <div>
          <p className="eyebrow">A MEMORY GAME</p>
          <h1>NEON PAIRS</h1>
          <p className="intro">Find every matching pair in as few moves as you can.</p>
        </div>
        <div className="header-mark" aria-hidden="true"><span /><span /><span /></div>
      </header>

      <section className="game-panel" aria-label="Game">
        <div className="deal-controls">
          <div className="size-control">
            <label htmlFor="grid-size">Grid size</label>
            <select id="grid-size" value={session.game.board.size} onChange={(event) => chooseSize(event.currentTarget.value)}>
              {supportedSizes.map((size) => <option key={size} value={size}>{size}x{size}</option>)}
            </select>
          </div>
          <div className="start-controls">
            <button type="button" onClick={session.newGame}>New Game</button>
            <button type="button" onClick={session.restart}>Restart</button>
            {session.isPaused && <button type="button" onClick={resume}>Resume</button>}
          </div>
        </div>

        <div className="score-strip">
          <p>Moves: <strong>{session.game.moves}</strong></p>
          <p>Pairs: <strong>{pairs}/{session.game.board.deck.length / 2}</strong></p>
          <p>Time: <strong>{formatElapsed(session.game.elapsedMs)}</strong></p>
          <p>Best: <strong>{session.bestScore ?? "none"}</strong></p>
        </div>

        {won && (
          <section className={`win-banner${session.isCelebrating ? " is-celebrating" : ""}`} aria-label="Game complete">
            <p className="win-kicker">ALL PAIRS FOUND</p>
            <p className="win-summary">Completed in {session.game.moves} moves</p>
            <p className="win-time">Time: {formatElapsed(session.game.elapsedMs)}</p>
          </section>
        )}

        <Board key={session.boardRevision} ref={boardRef} game={session.game} onActivate={session.activate} />
        {session.isPaused && <p className="pause-note">Progress is paused. Select Resume to continue.</p>}
      </section>

      <div className="sr-announcer" role="status" aria-live="polite" aria-atomic="true">
        <span key={session.announcement.id}>{session.announcement.text}</span>
      </div>

      <ReproductionControls
        boardCode={boardCodeDraft}
        snapshotText={snapshotDraft}
        loadStatus={session.loadStatus}
        onBoardCodeChange={setBoardCodeDraft}
        onSnapshotTextChange={setSnapshotDraft}
        onLoadBoard={() => { session.loadBoard(boardCodeDraft); }}
        onLoadSnapshot={() => { session.loadSnapshot(snapshotDraft); }}
        onExportSnapshot={exportSnapshot}
      />

      <footer className="game-footer">Every face has a shape, marker and fill to help you remember it.</footer>
    </main>
  );
}
import "./reproduction.css";

export type ReproductionProps = Readonly<{
  boardCode: string;
  snapshotText: string;
  loadStatus: string;
  onBoardCodeChange(value: string): void;
  onSnapshotTextChange(value: string): void;
  onLoadBoard(): void;
  onLoadSnapshot(): void;
  onExportSnapshot(): void;
}>;

export function ReproductionControls(props: ReproductionProps) {
  return (
    <details className="reproduction-panel">
      <summary>Reproduce a game</summary>
      <div className="reproduction-fields">
        <form onSubmit={(event) => { event.preventDefault(); props.onLoadBoard(); }}>
          <label htmlFor="board-code">Board code</label>
          <div className="control-row">
            <input
              id="board-code"
              type="text"
              maxLength={32}
              value={props.boardCode}
              onChange={(event) => props.onBoardCodeChange(event.currentTarget.value)}
              aria-invalid={props.loadStatus === "Invalid board code."}
            />
            <button type="submit">Load board</button>
          </div>
        </form>

        <div className="snapshot-tools">
          <label htmlFor="snapshot-json">Snapshot JSON</label>
          <textarea
            id="snapshot-json"
            maxLength={65536}
            rows={7}
            value={props.snapshotText}
            onChange={(event) => props.onSnapshotTextChange(event.currentTarget.value)}
            aria-invalid={props.loadStatus === "Invalid snapshot."}
          />
          <div className="control-row snapshot-actions">
            <button type="button" onClick={props.onExportSnapshot}>Export snapshot</button>
            <button type="button" onClick={props.onLoadSnapshot}>Load snapshot</button>
          </div>
        </div>

        <p className="reproduction-status" aria-live="off">{props.loadStatus}</p>
      </div>
    </details>
  );
}

